def deprecation_headers(sunset_date: str) -> dict:
    """Return the API deprecation headers with sunset_date in HTTP-date format."""
    return {
        "Deprecation": "true",
        "Sunset": sunset_date,
        "Link": '<https://developer.acme.example/migrate>; rel="deprecation"',
    }

import unittest

from api.headers import deprecation_headers


class DeprecationHeadersTests(unittest.TestCase):
    def test_headers_match_api_guidelines(self):
        sunset_date = "Wed, 01 Dec 2027 00:00:00 GMT"
        self.assertEqual(
            deprecation_headers(sunset_date),
            {
                "Deprecation": "true",
                "Sunset": sunset_date,
                "Link": '<https://developer.acme.example/migrate>; rel="deprecation"',
            },
        )

    def test_sunset_date_is_preserved(self):
        sunset_date = "Thu, 01 Jan 2026 12:34:56 GMT"
        self.assertEqual(deprecation_headers(sunset_date)["Sunset"], sunset_date)

    def test_each_call_returns_a_new_dictionary(self):
        headers = deprecation_headers("Wed, 01 Dec 2027 00:00:00 GMT")
        headers["Deprecation"] = "false"
        self.assertEqual(
            deprecation_headers("Wed, 01 Dec 2027 00:00:00 GMT")["Deprecation"],
            "true",
        )


if __name__ == "__main__":
    unittest.main()
